Apply a checks-effects-interactions pattern: store the provider in `_roleProviders` BEFORE making the external call, or use a reentrancy guard. Alternatively, check if the provider is already registered before pushing to the array:

function addRoleProvider(address providerAddress, uint32 timeToLive) external onlyBorrower {
    RoleProvider provider = _roleProviders[providerAddress];
    if (provider.isNull()) {
        // Store a placeholder first to prevent reentrancy
        _roleProviders[providerAddress] = encodeRoleProvider(timeToLive, providerAddress, NotPullProviderIndex);
        bool isPullProvider = IRoleProvider(providerAddress).isPullProvider();
        uint24 index = isPullProvider ? uint24(_pullProviders.length) : NotPullProviderIndex;
        provider = encodeRoleProvider(timeToLive, providerAddress, index);
        if (isPullProvider) _pullProviders.push(provider);
        _roleProviders[providerAddress] = provider;
        emit RoleProviderAdded(...);
    } else { ... }
}

