Add a reentrancy guard to all hook functions that make external calls:

uint256 private _reentrancyStatus;
modifier nonReentrant() {
    require(_reentrancyStatus != 2, 'Reentrant call');
    _reentrancyStatus = 2;
    _;
    _reentrancyStatus = 1;
